CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'All Fruits', price NUMERIC(10,2) NOT NULL CHECK (price >= 0), unit TEXT NOT NULL DEFAULT 'kg', image_url TEXT NOT NULL, stock NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (stock >= 0), availability BOOLEAN NOT NULL DEFAULT true, discount NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (discount >= 0 AND discount <= 100), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
